   <table>
     <thead>" & thead & "</thead>
     <tbody>" & rows & "</tbody>
     <tfoot>" & tfoot & "</tfoot>
   </table>
  </body></html>"
] ;

"data:text/html;base64," & Base64EncodeRFC ( 4648 ; html )
)

Let ( 
[
/* ========= CSS ========= */
css = 
"<!doctype html><html lang='ja'><head><meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1'>
<style>
html,body{margin:0;padding:0;width:100%;height:100%;background:#fff;overflow:hidden;box-sizing:border-box}
*{box-sizing:border-box}
.container{display:flex;flex-direction:column;gap:3px;width:100%;height:100%;padding:2px}
table{border-collapse:collapse;width:100%;font-size:11.5px;table-layout:auto}
th,td{border:1px solid #444;padding:2px 4px;line-height:1.15;text-align:right;white-space:normal;word-break:break-all;position:relative;transition:background-color .12s,outline-color .12s}

/* デフォルトヘッダー（白） */
th{background:#ffffff;text-align:center}

/* 1列目は左寄せ */
td:first-child,th:first-child{text-align:left}

/* 専売～テレマ：ヘッダー&データを黄色 */
th:nth-child(8),th:nth-child(9),th:nth-child(10),
td:nth-child(8),td:nth-child(9),td:nth-child(10){background:#fff7a8}

/* 完工～最終差異：ヘッダーだけ青 / データは白 */
th:nth-child(n+11){background:#a8d3ff}
td:nth-child(n+11){background:#ffffff}

/* ホバーなど */
td:hover{background:#ffec99!important;outline:2px solid rgba(255,180,0,.9);outline-offset:-2px}
tr:hover td{filter:brightness(1.02)}
tr.total td{background:none!important;font-weight:bold}

/* 符号色 */
td.positive{color:#087443;font-weight:bold}
td.negative{color:#b42318;font-weight:bold}
</style></head><body><div class='container'>";


/* ── 年月フィルタ（空なら前月） ── */
selYM_text = GetAsText ( 計画進捗::年月_g ) ;
_today = Get ( 日付 ) ;
prevYM = Case ( Month ( _today ) = 1 ; ( Year ( _today ) - 1 ) * 100 + 12 ; Year ( _today ) * 100 + ( Month ( _today ) - 1 ) ) ;
selYM_num = Case ( IsEmpty ( selYM_text ) ; prevYM ; GetAsNumber ( selYM_text ) ) ;

/* ── ヘッダ ── */
thead = 
"  <tr>
     <th>担当別</th><th>前月繰越</th><th>当月目標</th><th>実績</th>
     <th>卸受注完了</th><th>受注残</th><th>達成率</th>
     <th>専売</th><th>併売</th><th>テレマ</th>
     <th>完工</th><th>最終予測</th><th>中間予測</th>
     <th>総受注</th><th>当月受注</th><th>最終差異</th>
   </tr>" ;

/* ========= 行だけ生成 ========= */
rows =
Let ([ 
  L_年月       = List ( 担当別進捗::年月 );
  L_担当者     = List ( 担当別進捗::担当者 );
  L_SVCD       = List ( 担当別進捗::SV担当者CD );
  L_前月繰越   = List ( 担当別進捗::前月繰越 );
  L_当月目標   = List ( 担当別進捗::当月目標 );
  L_実績       = List ( 担当別進捗::実績 );
  L_卸受注完了 = List ( 担当別進捗::卸受注完了 );
  L_受注残     = List ( 担当別進捗::受注残 );
  L_達成率     = List ( 担当別進捗::達成率 );
  L_専売       = List ( 担当別進捗::専売 );
  L_併売       = List ( 担当別進捗::併売 );
  L_テレマ     = List ( 担当別進捗::テレマ );
  L_完工       = List ( 担当別進捗::完工 );
  L_最終予測   = List ( 担当別進捗::最終予測 );
  L_中間予測   = List ( 担当別進捗::中間予測 );
  L_総受注     = List ( 担当別進捗::総受注 );
  L_当月受注   = List ( 担当別進捗::当月受注 );
  L_最終差異   = List ( 担当別進捗::最終差異 );
  n = ValueCount ( L_年月 )
];

While (
  [ i=1 ; html="" ] ;
  i ≤ n ;
  [
    _年月       = GetAsNumber ( GetValue ( L_年月 ; i ) );
    _担当者     = GetValue ( L_担当者 ; i );
    _SVCD_raw   = GetValue ( L_SVCD ; i );
    _SVCD_txt   = TrimAll ( GetAsText ( _SVCD_raw ) ; 1 ; 1 );
    _SVCD_num   = GetAsNumber ( _SVCD_raw );
    _SVCD_pad4  = Right ( "0000" & _SVCD_num ; 4 );

    _svname = ExecuteSQL (
      "SELECT \"SV担当者名\" FROM \"担当別進捗_ユーザーマスタ\" 
       WHERE \"SV担当者CD\" IN ( ? , ? , ? )" ;
      "" ; "" ; _SVCD_txt ; GetAsText ( _SVCD_num ) ; _SVCD_pad4
    );
    _SV担当者名 = Case ( IsEmpty ( _svname ) or _svname = "?" ; "" ; _svname );

    _前月繰越   = GetValue ( L_前月繰越 ; i );
    _当月目標   = GetValue ( L_当月目標 ; i );
    _実績       = GetValue ( L_実績 ; i );
    _卸受注完了 = GetValue ( L_卸受注完了 ; i );
    _受注残     = GetValue ( L_受注残 ; i );
    _達成率     = GetValue ( L_達成率 ; i );
    _専売       = GetValue ( L_専売 ; i );
    _併売       = GetValue ( L_併売 ; i );
    _テレマ     = GetValue ( L_テレマ ; i );
    _完工       = GetValue ( L_完工 ; i );
    _最終予測   = GetValue ( L_最終予測 ; i );
    _中間予測   = GetValue ( L_中間予測 ; i );
    _総受注     = GetValue ( L_総受注 ; i );
    _当月受注   = GetValue ( L_当月受注 ; i );
    _最終差異   = GetValue ( L_最終差異 ; i );

    matchYM = Case ( IsEmpty ( selYM_text ) ; 1 ; _年月 = selYM_num );

    _担当別表示 = Case ( not IsEmpty ( _SV担当者名 ) ; _SV担当者名 ; _担当者 );
    _達成率_disp = GetAsText ( _達成率 );

    /* ※ 最終差異は常に黒表示にするため cls は使わない */
    cls = ""; 

    row =
      "<tr>" &
        "<td>" & Substitute ( GetAsText ( _担当別表示 ) ;
              [ "&" ; "&amp;" ] ; [ "<" ; "&lt;" ] ; [ ">" ; "&gt;" ] ;
              [ "\"" ; "&quot;" ] ; [ "'" ; "&#39;" ] ) & "</td>" &
        "<td>" & GetAsText ( _前月繰越 ) & "</td>" &
        "<td>" & GetAsText ( _当月目標 ) & "</td>" &
        "<td>" & GetAsText ( _実績 ) & "</td>" &
        "<td>" & GetAsText ( _卸受注完了 ) & "</td>" &
        "<td>" & GetAsText ( _受注残 ) & "</td>" &
        "<td>" & _達成率_disp & "</td>" &
        "<td>" & GetAsText ( _専売 ) & "人</td>" &
        "<td>" & GetAsText ( _併売 ) & "人</td>" &
        "<td>" & GetAsText ( _テレマ ) & "人</td>" &
        "<td>" & GetAsText ( _完工 ) & "</td>" &
        "<td>" & GetAsText ( _最終予測 ) & "</td>" &
        "<td>" & GetAsText ( _中間予測 ) & "</td>" &
        "<td>" & GetAsText ( _総受注 ) & "</td>" &
        "<td>" & GetAsText ( _当月受注 ) & "</td>" &
        /* ▼ 16列目（最終差異）：クラス付与しない＝常に黒字 */
        "<td>" & GetAsText ( _最終差異 ) & "</td>" &
      "</tr>";

    html = html & Case ( matchYM ; row ; "" );
    i = i + 1
  ] ;
  html
)
);

/* ========= 出力（末尾に負数自動ハイライトJSを追加） ========= */
html = 
  css & 
  "<table>" & thead & rows & "</table>" &
  "</div>" &
  "<script>
  (function(){
    function parseVal(t){
      if(!t) return null;
      var s=String(t).trim()
        .replace(/\u2212/g,'-')   /* 全角マイナス → 半角 */
        .replace(/,/g,'')          /* 3桁区切り除去 */
        .replace(/\s/g,'');       /* 空白除去 */
      /* 末尾%は許容、末尾に'人'など単位がある場合は数値判定から除外 */
      if(/^-?\d+(?:\.\d+)?%?$/.test(s)){
        return parseFloat(s.replace(/%$/,''));
      }
      return null;
    }
    document.querySelectorAll('tbody td').forEach(function(td){
      if(td.cellIndex===0) return;      /* 1列目（担当名）は無視 */
      if(td.cellIndex===15) return;     /* 16列目（最終差異）は常に黒字なので無視 */
      var v=parseVal(td.textContent);
      if(v===null) return;
      if(v<0) td.classList.add('negative');  /* 負のみ赤太字 */
    });
  })();
  </script></body></html>"
] ;

"data:text/html;base64," & Base64EncodeRFC ( 4648 ; html )
)

Let ( [
/* ========= CSS/ヘッダ ========= */
css = 
"<!doctype html>
<html lang='ja'>
<head>
<meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1'>
<style>
html,body {
