      <th>卸受注完了</th><th>受注残</th><th>達成率</th>
      <th>専売</th><th>併売</th><th>テレマ</th>
      <th>完工</th><th>最終予測</th><th>中間予測</th><th>総受注</th><th>当月受注</th><th>最終差異</th>
    </tr>" ;

/* =========================
