    _受注残     = GetNthRecord ( 拠点別計画進捗::受注残 ; i ) ;
    _達成率     = GetNthRecord ( 拠点別計画進捗::達成率 ; i ) ;
    _専売       = GetNthRecord ( 拠点別計画進捗::c_専売人数 ; i ) ;
    _併売       = GetNthRecord ( 拠点別計画進捗::c_併売人数 ; i ) ;
