    _完工       = GetNthRecord ( 拠点別計画進捗::完工 ; i ) ;
    _最終予測   = GetNthRecord ( 拠点別計画進捗::最終予測 ; i ) ;
    _中間予測   = GetNthRecord ( 拠点別計画進捗::中間予測 ; i ) ;
