    _中間予測   = GetNthRecord ( 拠点別計画進捗::中間予測 ; i ) ;
    _総受注     = GetNthRecord ( 拠点別計画進捗::総受注 ; i ) ;
    _当月受注   = GetNthRecord ( 拠点別計画進捗::当月受注 ; i ) ;
    _最終差異   = GetNthRecord ( 拠点別計画進捗::最終差異 ; i ) ;

    matchYM = Case ( IsEmpty ( selYM_text ) ; 1 ; _年月 = selYM_num ) ;
    show    = Case ( _分類 = "中堅販路" and matchYM ; 1 ; 0 ) ;

    /* 負のみ negative */
    cls = Case ( GetAsNumber ( _最終差異 ) < 0 ; "negative" ; "" ) ;

    _達成率_disp = GetAsText ( _達成率 ) ;
    _運営会社_out = GetAsText ( _運営会社 ) ;

    row =
      "<tr>" &
        "<td>" & Substitute ( GetAsText ( _拠点名 ) ;
              [ "&" ; "&amp;" ] ; [ "<" ; "&lt;" ] ; [ ">" ; "&gt;" ] ;
              [ "\"" ; "&quot;" ] ; [ "'" ; "&#39;" ] ) & "</td>" &
        "<td style='text-align:left'>" & Substitute ( _運営会社_out ;
              [ "&" ; "&amp;" ] ; [ "<" ; "&lt;" ] ; [ ">" ; "&gt;" ] ;
              [ "\"" ; "&quot;" ] ; [ "'" ; "&#39;" ] ) & "</td>" &
        "<td>" & GetAsText ( _前月繰越 ) & "</td>" &
        "<td>" & GetAsText ( _当月目標 ) & "</td>" &
        "<td>" & GetAsText ( _実績 ) & "</td>" &
        "<td>" & GetAsText ( _卸受注完了 ) & "</td>" &
        "<td>" & GetAsText ( _受注残 ) & "</td>" &
        "<td>" & _達成率_disp & "</td>" &
        "<td>" & GetAsText ( _専売 ) & "</td>" &
        "<td>" & GetAsText ( _併売 ) & "</td>" &
        "<td>" & GetAsText ( _テレマ人数 ) & "</td>" &
        "<td>" & GetAsText ( _完工 ) & "</td>" &
        "<td>" & GetAsText ( _最終予測 ) & "</td>" &
        "<td>" & GetAsText ( _中間予測 ) & "</td>" &
        "<td>" & GetAsText ( _総受注 ) & "</td>" &
        "<td>" & GetAsText ( _当月受注 ) & "</td>" &
        "<td class='" & cls & "'>" & GetAsText ( _最終差異 ) & "</td>" &
      "</tr>" ;

    html = html & Case ( show ; row ; "" ) ;
    i = i + 1
  ] ;
  html
) ) ;

C_list =
Let ([
  kbn = "中堅販路" ;
  sql_text =
  "SELECT \"前月繰越\",\"当月目標\",\"実績\",\"卸受注完了\",\"受注残\",
          \"達成率\",
          \"専売\",\"併売\",\"テレマ\",\"完工\",
          \"最終予測\",\"中間予測\",\"総受注\",\"当月受注\",
          \"最終差異\"
   FROM \"拠点別計画進捗_集計\"
   WHERE \"分類\" = ? AND \"年月\" = ?" ;
  sql_num = sql_text ;

  r1 = ExecuteSQL ( sql_text ; "|" ; "" ; kbn ; selYM_text ) ;
  r2 = Case ( ( r1 = "?" or IsEmpty ( r1 ) ) and not IsEmpty ( selYM_num ) ;
              ExecuteSQL ( sql_num ; "|" ; "" ; kbn ; selYM_num ) ; "" ) ;

  raw = Case ( not IsEmpty ( r1 ) and r1 ≠ "?" ; r1 ;
               not IsEmpty ( r2 ) and r2 ≠ "?" ; r2 ;
               "" )
] ; Substitute ( raw ; "|" ; "¶" ) ) ;

tC_前月繰越   = GetAsNumber ( GetValue ( C_list ;  1 ) ) ;
tC_当月目標   = GetAsNumber ( GetValue ( C_list ;  2 ) ) ;
tC_実績       = GetAsNumber ( GetValue ( C_list ;  3 ) ) ;
tC_卸受注完了 = GetAsNumber ( GetValue ( C_list ;  4 ) ) ;
tC_受注残     = GetAsNumber ( GetValue ( C_list ;  5 ) ) ;
tC_達成率表示 =                 GetValue ( C_list ;  6 ) ;
tC_専売       = GetAsNumber ( GetValue ( C_list ;  7 ) ) ;
tC_併売       = GetAsNumber ( GetValue ( C_list ;  8 ) ) ;
tC_テレマ     = GetAsNumber ( GetValue ( C_list ;  9 ) ) ;
tC_完工       = GetAsNumber ( GetValue ( C_list ; 10 ) ) ;
tC_最終予測   = GetAsNumber ( GetValue ( C_list ; 11 ) ) ;
tC_中間予測   = GetAsNumber ( GetValue ( C_list ; 12 ) ) ;
tC_総受注     = GetAsNumber ( GetValue ( C_list ; 13 ) ) ;
tC_当月受注   = GetAsNumber ( GetValue ( C_list ; 14 ) ) ;
tC_最終差異   = GetAsNumber ( GetValue ( C_list ; 15 ) ) ;

totalRowC =
"<tr class='total'>" &
  "<td colspan='2'>合計</td>" &
  "<td>" & tC_前月繰越 & "</td>" &
  "<td>" & tC_当月目標 & "</td>" &
  "<td>" & tC_実績 & "</td>" &
  "<td>" & tC_卸受注完了 & "</td>" &
  "<td>" & tC_受注残 & "</td>" &
  "<td>" & tC_達成率表示 & "</td>" &
  "<td>" & tC_専売 & "</td>" &
  "<td>" & tC_併売 & "</td>" &
  "<td>" & tC_テレマ & "</td>" &
  "<td>" & tC_完工 & "</td>" &
  "<td>" & tC_最終予測 & "</td>" &
  "<td>" & tC_中間予測 & "</td>" &
  "<td>" & tC_総受注 & "</td>" &
  "<td>" & tC_当月受注 & "</td>" &
  "<td>" & tC_最終差異 & "</td>" &
"</tr>" ;

/* ========= 仕上げHTML ========= */
html = 
  css &
  "<h3>大手販路</h3>
   <table>" & thead & rowsA & totalRowA & "</table>" &
  "<h3>主力販路</h3>
   <table>" & thead & rowsB & totalRowB & "</table>" &
  "<h3>中堅販路</h3>
   <table>" & thead & rowsC & totalRowC & "</table>" &
  /* 負の値だけ赤に */
  "<script>(function(){function p(s){if(!s)return null;let t=String(s).trim().replace(/\u2212/g,'-').replace(/,/g,'').replace(/\s/g,'');if(/^-?\d+(\.\d+)?%?$/.test(t)){return parseFloat(t.replace(/%$/,''));}return null;}document.querySelectorAll('td').forEach(function(td){var v=p(td.textContent);if(v===null)return;if(v<0)td.classList.add('negative');});})();</script>" &
  "</body></html>"
] ;

"data:text/html;base64," & Base64EncodeRFC ( 4648 ; html )
)

Let ( 
[
/* ================== レイアウト ================== */
css = 
"<!doctype html><html lang='ja'><head><meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1, viewport-fit=cover'>
<style>
  :root{--ink:#111827;--muted:#6b7280;--line:#9aa7bd;--headTitle:#4B6382;--headCol:#f2f2f2;--rowAlt:#f7f9fc;--red:#fce2e2;}
  *{box-sizing:border-box}
  html,body{height:auto;overflow:visible;}
  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Hiragino Kaku Gothic ProN','Meiryo',sans-serif;margin:0;padding:0;color:var(--ink);
       -webkit-text-size-adjust:100%;font-size:clamp(10.5px,1.05vw,12px);line-height:1.2;background:#fff;}
  h3{margin:0 0 2px;padding:2px 8px;border:1px solid var(--line);background:var(--headTitle);color:#fff;text-align:center;font-weight:700;line-height:1.15;font-size:0.9em}
  table{border-collapse:collapse;border-spacing:0;width:100%;font-size:0.85em;border:1px solid var(--line);margin:0;table-layout:auto}
  thead th{background:var(--headCol);border-bottom:1px solid var(--line);border-right:1px solid #c7d2e1;padding:3px 6px;text-align:center;white-space:nowrap;color:#111;font-weight:700;line-height:1.12;font-size:1.0em}
  thead th:last-child{border-right:0}
  thead th.sumcol{background:#ffe36e}
  tbody td{border-bottom:1px solid #c7d2e1;border-right:1px solid #c7d2e1;padding:3px 6px;vertical-align:middle;background:#fff;line-height:1.12}
  tbody tr:nth-child(even) td{background:var(--rowAlt)}
  tbody td:last-child{border-right:0}
  td.day{font-weight:700;text-align:center;min-width:36px}
  td.num{font-variant-numeric:tabular-nums;text-align:right}
  td.pct{text-align:center;font-variant-numeric:tabular-nums}
  .emptyRed{background:var(--red)!important}
  .neg{color:#ef4444;font-weight:700}
  .pos{color:#111827;font-weight:400}
  td.sep, th.sep{border-left:2px solid #5b6b82}
  tfoot td{background:#fafafa;border-top:2px solid #5b6b82;font-weight:700;padding:3px 6px}
</style></head><body>";

thead =
"  <tr>
      <th>日</th>
      <th>必要売上</th><th>計上売上</th><th>差異金額</th>
      <th>必要進捗</th><th>実績進捗</th><th>前月</th><th>対比</th>
      <th class='sep sumcol'>日計</th><th class='sumcol'>進捗率</th>
    </tr>";

/* 空行テンプレ（休日=赤／平日=白） */
emptyRedTpl =
"<tr><td class='day'>§日</td>
<td class='num emptyRed'></td><td class='num emptyRed'></td><td class='num emptyRed'></td>
<td class='pct emptyRed'></td><td class='pct emptyRed'></td>
<td class='num emptyRed'></td><td class='num emptyRed'></td>
<td class='num sep emptyRed'></td><td class='pct emptyRed'></td></tr>";

emptyWhiteTpl =
"<tr><td class='day'>§日</td>
<td class='num'></td><td class='num'></td><td class='num'></td>
<td class='pct'></td><td class='pct'></td>
<td class='num'></td><td class='num'></td>
<td class='num sep'></td><td class='pct'></td></tr>";

/* ========= 年月フィルタとタイトル用（YYYYMM想定） ========= */
selYM_text = GetAsText ( 計画進捗::年月_g ) ;
selYM_num  = GetAsNumber ( selYM_text ) ;
ymN   = Case ( IsEmpty ( selYM_num ) ; Year ( Get ( 日付 ) ) * 100 + Month ( Get ( 日付 ) ) ; selYM_num ) ;
y     = Floor ( ymN / 100 ) ;
m     = Mod ( ymN ; 100 ) ;
titleMonth = m ;
monthDays  = Day ( Date ( m + 1 ; 0 ; y ) ) ;  /* 当月末日 */

/* 分類（固定指定） */
category = "ドゥオモインターナショナル" ;

/* ========= 休日マスタ照会のダミー定義（While内でSQL実行するため） ========= */
FN_isHoliday = Let ( [ _date = GetAsDate ( Get ( 計算式繰り返し位置番号 ) ) ] ; "" ) ;

/* ========= 行生成 ========= */
rows = While (
  [ d = 1 ; html = "" ] ;
  d ≤ monthDays ;
  [
    /* 日データ取得（文字→数値フォールバック）— 直書きSQL＋分類条件付き */
    r1 = ExecuteSQL (
"SELECT
  \"稼働日\",
  \"必要売上\",
  \"計上売上\",
  \"必要進捗\",
  \"実績進捗\",
  \"前月\",
  \"対比\",
  \"日計\",
  \"進捗率\"
FROM
  \"稼働日重要指数\"
WHERE
  \"年月\" = ? AND
  \"日\" = ? AND
  \"重要指数分類\" = ?
" ; "|" ; "" ; selYM_text ; d ; category ) ;

    r2 = Case (
           ( r1 = "?" or IsEmpty ( r1 ) ) and not IsEmpty ( selYM_num ) ;
           ExecuteSQL (
"SELECT
  \"稼働日\",
  \"必要売上\",
  \"計上売上\",
  \"必要進捗\",
  \"実績進捗\",
  \"前月\",
  \"対比\",
  \"日計\",
  \"進捗率\"
FROM
  \"稼働日重要指数\"
WHERE
  \"年月\" = ? AND
  \"日\" = ? AND
  \"重要指数分類\" = ?
" ; "|" ; "" ; selYM_num ; d ; category ) ;
           "" ) ;

    raw  = Case ( not IsEmpty ( r1 ) and r1 ≠ "?" ; r1 ;
                  not IsEmpty ( r2 ) and r2 ≠ "?" ; r2 ; "" ) ;
    vals = Substitute ( raw ; "|" ; "¶" ) ;

    /* 列インデックス（先頭に「稼働日」を追加したため、以降+1） */
    _稼働日      = GetAsNumber ( GetValue ( vals ; 1 ) ) ;
    _必要売上    = GetAsNumber ( GetValue ( vals ; 2 ) ) ;
    _計上売上    = GetAsNumber ( GetValue ( vals ; 3 ) ) ;
    _必要進捗    = GetValue     ( vals ; 4 ) ;
    _実績進捗    = GetValue     ( vals ; 5 ) ;
    _前月        = GetAsNumber ( GetValue ( vals ; 6 ) ) ;
    _対比        = GetAsNumber ( GetValue ( vals ; 7 ) ) ;
    _日計        = GetAsNumber ( GetValue ( vals ; 8 ) ) ;
    _進捗率      = GetValue     ( vals ; 9 ) ;

    /* 差額・率整形 */
    _差額 = Case ( not IsEmpty ( raw ) ; _計上売上 - _必要売上 ; "" ) ;

    /* ▼ 必要進捗 % 付与（空なら計上/必要×100で補完） */
    _必要進捗_disp = Case (
      IsEmpty ( _必要進捗 ) ;
        Case ( _必要売上 > 0 and not IsEmpty ( _計上売上 ) ;
               Round ( _計上売上 / _必要売上 * 100 ; 0 ) & "%" ;
               "" ) ;
      PatternCount ( _必要進捗 ; "%" ) > 0 ; _必要進捗 ;
      _必要進捗 & "%"
    ) ;

    /* ▼ 実績進捗 % 付与（値があれば%付与、既に%ならそのまま） */
    _実績進捗_disp = Case (
      IsEmpty ( _実績進捗 ) ; "" ;
      PatternCount ( _実績進捗 ; "%" ) > 0 ; _実績進捗 ;
      _実績進捗 & "%"
    ) ;

    /* ▼ 進捗率（列10）の表示整形（%付与） */
    _進捗率_disp = Case (
      IsEmpty ( _進捗率 ) ; "" ;
      PatternCount ( _進捗率 ; "%" ) > 0 ; _進捗率 ;
      _進捗率 & "%"
    ) ;

    /* ▼ 休日判定（休日マスタ::日付 = 日付 or 'YYYY/MM/DD'） */
    dayDate = Date ( m ; d ; y ) ;
    h_sql = "SELECT COUNT(*) FROM \"休日マスタ\" WHERE \"日付\" = ?" ;
    h1 = ExecuteSQL ( h_sql ; "" ; "" ; GetAsDate ( dayDate ) ) ;
    h2 = Case (
           ( h1 = "?" or IsEmpty ( h1 ) ) ;
           ExecuteSQL ( h_sql ; "" ; "" ;
             Year ( dayDate ) & "/" & Right ( "0" & Month ( dayDate ) ; 2 ) & "/" & Right ( "0" & Day ( dayDate ) ; 2 )
           ) ;
           ""
         ) ;
    isHoliday = GetAsNumber ( Case ( not IsEmpty ( h1 ) and h1 ≠ "?" ; h1 ;
                                     not IsEmpty ( h2 ) and h2 ≠ "?" ; h2 ; 0 ) ) > 0 ;
    tdCls = Case ( isHoliday ; " emptyRed" ; "" ) ;

    /* ▼ マイナス値の赤字クラス判定（差額は従来どおり pos/neg を使用） */
    clsNec  = Case ( GetAsNumber ( _必要売上 ) < 0 ; "neg" ; "" ) ;
    clsAct  = Case ( GetAsNumber ( _計上売上 ) < 0 ; "neg" ; "" ) ;
    clsPre  = Case ( GetAsNumber ( _前月 )     < 0 ; "neg" ; "" ) ;
    clsComp = Case ( GetAsNumber ( _対比 )     < 0 ; "neg" ; "" ) ;
    clsDay  = Case ( GetAsNumber ( _日計 )     < 0 ; "neg" ; "" ) ;
    clsDiff = Case ( GetAsNumber ( _差額 )     < 0 ; "neg" ; "pos" ) ;

    /* ▼ データ行 or 空行（休日だけ赤） */
    rowData =
      Case ( IsEmpty ( raw ) ; "" ;
        "<tr>" &
          "<td class='day" & tdCls & "'>" & d & "日</td>" &
          "<td class='num " & clsNec  & tdCls & "'>" & _必要売上 & "</td>" &
          "<td class='num " & clsAct  & tdCls & "'>" & _計上売上 & "</td>" &
          "<td class='num " & clsDiff & tdCls & "'>" & _差額 & "</td>" &
          "<td class='pct" & tdCls & "'>" & _必要進捗_disp & "</td>" &
          "<td class='pct" & tdCls & "'>" & _実績進捗_disp & "</td>" &
          "<td class='num " & clsPre  & tdCls & "'>" & _前月 & "</td>" &
          "<td class='num " & clsComp & tdCls & "'>" & _対比 & "</td>" &
          "<td class='num sep " & clsDay & tdCls & "'>" & _日計 & "</td>" &
          "<td class='pct" & tdCls & "'>" & _進捗率_disp & "</td>" &
        "</tr>"
      ) ;

    rowEmpty =
      Case ( isHoliday ;
             Substitute ( emptyRedTpl   ; "§" ; d ) ;
             Substitute ( emptyWhiteTpl ; "§" ; d ) ) ;

    html = html & Case ( IsEmpty ( rowData ) ; rowEmpty ; rowData ) ;

    d = d + 1
  ] ;
  html
) ;

/* ===== フッター（日計の合計：同テーブル＋分類条件付き） ===== */
foot_val = Let ([
  s1 = ExecuteSQL (
"SELECT SUM(\"日計\")
 FROM \"稼働日重要指数\"
 WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_text ; category ) ;
  s2 = Case ( ( s1 = "?" or IsEmpty ( s1 ) ) and not IsEmpty ( selYM_num ) ;
              ExecuteSQL (
"SELECT SUM(\"日計\")
 FROM \"稼働日重要指数\"
 WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_num ; category ) ;
              "" ) ;
  v  = Case ( not IsEmpty ( s1 ) and s1 ≠ "?" ; s1 ;
              not IsEmpty ( s2 ) and s2 ≠ "?" ; s2 ; "" )
] ; v ) ;

tfoot =
"<tr><td class='num' colspan='9' style='text-align:right;padding-right:12px'></td>
  <td class='num' style='background:#fff'>" & foot_val & "</td></tr>";

/* ========= 仕上げHTML ========= */
html =
  css &
  "<h3>＊" & titleMonth & "月度稼働日重要指数（ドゥオモインターナショナル）</h3>
   <table>
     <thead>" & thead & "</thead>
     <tbody>" & rows & "</tbody>
     <tfoot>" & tfoot & "</tfoot>
   </table>
  </body></html>"
] ;

"data:text/html;base64," & Base64EncodeRFC ( 4648 ; html )
)

Let ( 
[
/* ================== レイアウト ================== */
css = 
"<!doctype html><html lang='ja'><head><meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1, viewport-fit=cover'>
<style>
  :root{--ink:#111827;--muted:#6b7280;--line:#9aa7bd;--headTitle:#4B6382;--headCol:#f2f2f2;--rowAlt:#f7f9fc;--red:#fce2e2;}
  *{box-sizing:border-box}
  html,body{height:auto;overflow:visible;}
  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Hiragino Kaku Gothic ProN','Meiryo',sans-serif;margin:0;padding:0;color:var(--ink);
       -webkit-text-size-adjust:100%;font-size:clamp(10.5px,1.05vw,12px);line-height:1.2;background:#fff;}
  h3{margin:0 0 2px;padding:2px 8px;border:1px solid var(--line);background:var(--headTitle);color:#fff;text-align:center;font-weight:700;line-height:1.15;font-size:0.9em}
  table{border-collapse:collapse;border-spacing:0;width:100%;font-size:0.85em;border:1px solid var(--line);margin:0;table-layout:auto}
  thead th{background:var(--headCol);border-bottom:1px solid var(--line);border-right:1px solid #c7d2e1;padding:3px 6px;text-align:center;white-space:nowrap;color:#111;font-weight:700;line-height:1.12;font-size:1.0em}
  thead th:last-child{border-right:0}
  thead th.sumcol{background:#ffe36e}
  tbody td{border-bottom:1px solid #c7d2e1;border-right:1px solid #c7d2e1;padding:3px 6px;vertical-align:middle;background:#fff;line-height:1.12}
  tbody tr:nth-child(even) td{background:var(--rowAlt)}
  tbody td:last-child{border-right:0}
  td.day{font-weight:700;text-align:center;min-width:36px}
  td.num{font-variant-numeric:tabular-nums;text-align:right}
  td.pct{text-align:center;font-variant-numeric:tabular-nums}
  .emptyRed{background:var(--red)!important}
  .neg{color:#ef4444;font-weight:700}
  .pos{color:#111827;font-weight:400}
  td.sep, th.sep{border-left:2px solid #5b6b82}
  tfoot td{background:#fafafa;border-top:2px solid #5b6b82;font-weight:700;padding:3px 6px}
</style></head><body>";

thead =
"  <tr>
      <th>日</th>
      <th>必要売上</th><th>計上売上</th><th>差異金額</th>
      <th>必要進捗</th><th>実績進捗</th><th>前月</th><th>対比</th>
      <th class='sep sumcol'>日計</th><th class='sumcol'>進捗率</th>
    </tr>";

/* 空行テンプレ（休日=赤／平日=白） */
emptyRedTpl =
"<tr><td class='day'>§日</td>
<td class='num emptyRed'></td><td class='num emptyRed'></td><td class='num emptyRed'></td>
<td class='pct emptyRed'></td><td class='pct emptyRed'></td>
<td class='num emptyRed'></td><td class='num emptyRed'></td>
<td class='num sep emptyRed'></td><td class='pct emptyRed'></td></tr>";

emptyWhiteTpl =
"<tr><td class='day'>§日</td>
<td class='num'></td><td class='num'></td><td class='num'></td>
<td class='pct'></td><td class='pct'></td>
<td class='num'></td><td class='num'></td>
<td class='num sep'></td><td class='pct'></td></tr>";

/* ========= 年月フィルタとタイトル用（YYYYMM想定） ========= */
selYM_text = GetAsText ( 計画進捗::年月_g ) ;
selYM_num  = GetAsNumber ( selYM_text ) ;
ymN   = Case ( IsEmpty ( selYM_num ) ; Year ( Get ( 日付 ) ) * 100 + Month ( Get ( 日付 ) ) ; selYM_num ) ;
y     = Floor ( ymN / 100 ) ;
m     = Mod ( ymN ; 100 ) ;
titleMonth = m ;
monthDays  = Day ( Date ( m + 1 ; 0 ; y ) ) ;  /* 当月末日 */

/* 分類（固定指定） */
category = "D以外委託販路" ;

/* ========= 休日マスタ照会のダミー定義（While内でSQL実行するため） ========= */
FN_isHoliday = Let ( [ _date = GetAsDate ( Get ( 計算式繰り返し位置番号 ) ) ] ; "" ) ;

/* ========= 行生成 ========= */
rows = While (
  [ d = 1 ; html = "" ] ;
  d ≤ monthDays ;
  [
    /* 日データ取得（文字→数値フォールバック）— 直書きSQL＋分類条件付き */
    r1 = ExecuteSQL (
"SELECT
  \"稼働日\",
  \"必要売上\",
  \"計上売上\",
  \"必要進捗\",
  \"実績進捗\",
  \"前月\",
  \"対比\",
  \"日計\",
  \"進捗率\"
FROM
  \"稼働日重要指数\"
WHERE
  \"年月\" = ? AND
  \"日\" = ? AND
  \"重要指数分類\" = ?
" ; "|" ; "" ; selYM_text ; d ; category ) ;

    r2 = Case (
           ( r1 = "?" or IsEmpty ( r1 ) ) and not IsEmpty ( selYM_num ) ;
           ExecuteSQL (
"SELECT
  \"稼働日\",
  \"必要売上\",
  \"計上売上\",
  \"必要進捗\",
  \"実績進捗\",
  \"前月\",
  \"対比\",
  \"日計\",
  \"進捗率\"
FROM
  \"稼働日重要指数\"
WHERE
  \"年月\" = ? AND
  \"日\" = ? AND
  \"重要指数分類\" = ?
" ; "|" ; "" ; selYM_num ; d ; category ) ;
           "" ) ;

    raw  = Case ( not IsEmpty ( r1 ) and r1 ≠ "?" ; r1 ;
                  not IsEmpty ( r2 ) and r2 ≠ "?" ; r2 ; "" ) ;
    vals = Substitute ( raw ; "|" ; "¶" ) ;

    /* 列インデックス（先頭に「稼働日」を追加したため、以降+1） */
    _稼働日      = GetAsNumber ( GetValue ( vals ; 1 ) ) ;
    _必要売上    = GetAsNumber ( GetValue ( vals ; 2 ) ) ;
    _計上売上    = GetAsNumber ( GetValue ( vals ; 3 ) ) ;
    _必要進捗    = GetValue     ( vals ; 4 ) ;
    _実績進捗    = GetValue     ( vals ; 5 ) ;
    _前月        = GetAsNumber ( GetValue ( vals ; 6 ) ) ;
    _対比        = GetAsNumber ( GetValue ( vals ; 7 ) ) ;
    _日計        = GetAsNumber ( GetValue ( vals ; 8 ) ) ;
    _進捗率      = GetValue     ( vals ; 9 ) ;

    /* 差額・率整形 */
    _差額 = Case ( not IsEmpty ( raw ) ; _計上売上 - _必要売上 ; "" ) ;
    clsDiff = Case ( GetAsNumber ( _差額 ) < 0 ; "neg" ; "pos" ) ;

    /* ▼ 必要進捗 % 付与（空なら計上/必要×100で補完） */
    _必要進捗_disp = Case (
      IsEmpty ( _必要進捗 ) ;
        Case ( _必要売上 > 0 and not IsEmpty ( _計上売上 ) ;
               Round ( _計上売上 / _必要売上 * 100 ; 0 ) & "%" ;
               "" ) ;
      PatternCount ( _必要進捗 ; "%" ) > 0 ; _必要進捗 ;
      _必要進捗 & "%"
    ) ;

    /* ▼ 実績進捗 % 付与（値があれば%付与、既に%ならそのまま） */
    _実績進捗_disp = Case (
      IsEmpty ( _実績進捗 ) ; "" ;
      PatternCount ( _実績進捗 ; "%" ) > 0 ; _実績進捗 ;
      _実績進捗 & "%"
    ) ;

    /* ▼ 進捗率（列10）の表示整形（%付与） */
    _進捗率_disp = Case (
      IsEmpty ( _進捗率 ) ; "" ;
      PatternCount ( _進捗率 ; "%" ) > 0 ; _進捗率 ;
      _進捗率 & "%"
    ) ;

    /* 休日判定（休日マスタ::日付 = 日付 or 'YYYY/MM/DD'） */
    dayDate = Date ( m ; d ; y ) ;
    h_sql = "SELECT COUNT(*) FROM \"休日マスタ\" WHERE \"日付\" = ?" ;
    h1 = ExecuteSQL ( h_sql ; "" ; "" ; GetAsDate ( dayDate ) ) ;
    h2 = Case (
           ( h1 = "?" or IsEmpty ( h1 ) ) ;
           ExecuteSQL ( h_sql ; "" ; "" ;
             Year ( dayDate ) & "/" & Right ( "0" & Month ( dayDate ) ; 2 ) & "/" & Right ( "0" & Day ( dayDate ) ; 2 )
           ) ;
           ""
         ) ;
    isHoliday = GetAsNumber ( Case ( not IsEmpty ( h1 ) and h1 ≠ "?" ; h1 ;
                                     not IsEmpty ( h2 ) and h2 ≠ "?" ; h2 ; 0 ) ) > 0 ;
    tdCls = Case ( isHoliday ; " emptyRed" ; "" ) ;

    /* ▼ マイナス値の赤字クラス（数値列） */
    clsNec  = Case ( GetAsNumber ( _必要売上 ) < 0 ; "neg" ; "" ) ;
    clsAct  = Case ( GetAsNumber ( _計上売上 ) < 0 ; "neg" ; "" ) ;
    clsPre  = Case ( GetAsNumber ( _前月 )     < 0 ; "neg" ; "" ) ;
    clsComp = Case ( GetAsNumber ( _対比 )     < 0 ; "neg" ; "" ) ;
    clsDay  = Case ( GetAsNumber ( _日計 )     < 0 ; "neg" ; "" ) ;

    /* データ行 or 空行（休日だけ赤） */
    rowData =
      Case ( IsEmpty ( raw ) ; "" ;
        "<tr>" &
          "<td class='day" & tdCls & "'>" & d & "日</td>" &
          "<td class='num " & clsNec  & tdCls & "'>" & _必要売上 & "</td>" &
          "<td class='num " & clsAct  & tdCls & "'>" & _計上売上 & "</td>" &
          "<td class='num " & clsDiff & tdCls & "'>" & _差額 & "</td>" &
          "<td class='pct" & tdCls & "'>" & _必要進捗_disp & "</td>" &
          "<td class='pct" & tdCls & "'>" & _実績進捗_disp & "</td>" &
          "<td class='num " & clsPre  & tdCls & "'>" & _前月 & "</td>" &
          "<td class='num " & clsComp & tdCls & "'>" & _対比 & "</td>" &
          "<td class='num sep " & clsDay & tdCls & "'>" & _日計 & "</td>" &
          "<td class='pct" & tdCls & "'>" & _進捗率_disp & "</td>" &
        "</tr>"
      ) ;

    rowEmpty =
      Case ( isHoliday ;
             Substitute ( emptyRedTpl   ; "§" ; d ) ;
             Substitute ( emptyWhiteTpl ; "§" ; d ) ) ;

    html = html & Case ( IsEmpty ( rowData ) ; rowEmpty ; rowData ) ;

    d = d + 1
  ] ;
  html
) ;

/* ===== フッター（日計の合計：同テーブル＋分類条件付き） ===== */
foot_val = Let ([
  s1 = ExecuteSQL (
"SELECT SUM(\"日計\")
 FROM \"稼働日重要指数\"
 WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_text ; category ) ;
  s2 = Case ( ( s1 = "?" or IsEmpty ( s1 ) ) and not IsEmpty ( selYM_num ) ;
              ExecuteSQL (
"SELECT SUM(\"日計\")
 FROM \"稼働日重要指数\"
 WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_num ; category ) ;
              "" ) ;
  v  = Case ( not IsEmpty ( s1 ) and s1 ≠ "?" ; s1 ;
              not IsEmpty ( s2 ) and s2 ≠ "?" ; s2 ; "" )
] ; v ) ;

tfoot =
"<tr><td class='num' colspan='9' style='text-align:right;padding-right:12px'></td>
  <td class='num' style='background:#fff'>" & foot_val & "</td></tr>";

/* ========= 仕上げHTML ========= */
html =
  css &
  "<h3>＊" & titleMonth & "月度稼働日重要指数（D以外委託販路）</h3>
   <table>
     <thead>" & thead & "</thead>
     <tbody>" & rows & "</tbody>
     <tfoot>" & tfoot & "</tfoot>
   </table>
  </body></html>"
] ;

"data:text/html;base64," & Base64EncodeRFC ( 4648 ; html )
)

Let ( 
[
/* ================== レイアウト ================== */
css = 
"<!doctype html><html lang='ja'><head><meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1, viewport-fit=cover'>
<style>
  :root{--ink:#111827;--muted:#6b7280;--line:#9aa7bd;--headTitle:#4B6382;--headCol:#f2f2f2;--rowAlt:#f7f9fc;}
  *{box-sizing:border-box}
  html,body{height:auto;overflow:visible;}
  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Hiragino Kaku Gothic ProN','Meiryo',sans-serif;margin:0;padding:0;color:var(--ink);
       -webkit-text-size-adjust:100%;font-size:clamp(10.5px,1.05vw,12px);line-height:1.2;background:#fff;}
  h3{margin:0 0 2px;padding:2px 8px;border:1px solid var(--line);background:var(--headTitle);color:#fff;text-align:center;font-weight:700;line-height:1.15;font-size:0.9em}
  table{border-collapse:collapse;border-spacing:0;width:100%;font-size:0.85em;border:1px solid var(--line);margin:0;table-layout:auto}
  thead th{background:var(--headCol);border-bottom:1px solid var(--line);border-right:1px solid #c7d2e1;padding:3px 6px;text-align:center;white-space:nowrap;color:#111;font-weight:700;line-height:1.12;font-size:1.0em}
  thead th:last-child{border-right:0}
  thead th.sumcol{background:#ffe36e}
  tbody td{border-bottom:1px solid #c7d2e1;border-right:1px solid #c7d2e1;padding:3px 6px;vertical-align:middle;background:#fff;line-height:1.12}
  tbody tr:nth-child(even) td{background:var(--rowAlt)}
  tbody td:last-child{border-right:0}
  td.day{font-weight:700;text-align:center;min-width:36px}
  td.num{font-variant-numeric:tabular-nums;text-align:right}
  td.pct{text-align:center;font-variant-numeric:tabular-nums}
  .neg{color:#ef4444;font-weight:700}
  .pos{color:#111827;font-weight:400}
  td.sep, th.sep{border-left:2px solid #5b6b82}
  tfoot td{background:#fafafa;border-top:2px solid #5b6b82;font-weight:700;padding:3px 6px}
</style></head><body>";

thead =
"  <tr>
      <th>日</th>
      <th>必要売上</th><th>計上売上</th><th>差額</th>
      <th>必要進捗</th><th>実績進捗</th><th>前月</th><th>対比</th>
      <th class='sep sumcol'>日計</th><th class='sumcol'>進捗率</th>
    </tr>";

/* ========= 年月フィルタとタイトル用 ========= */
selYM_text = GetAsText ( 計画進捗::年月_g ) ;
selYM_num  = GetAsNumber ( selYM_text ) ;
ymN   = Case ( IsEmpty ( selYM_num ) ; Year ( Get ( 日付 ) ) * 100 + Month ( Get ( 日付 ) ) ; selYM_num ) ;
y     = Floor ( ymN / 100 ) ;
m     = Mod ( ymN ; 100 ) ;
titleMonth = m ;

/* ========= 分類固定（FT業務委託） ========= */
category = "FT業務委託" ;

/* ========= 稼働日（上限22にクリップ） ========= */
workDays_raw1 = ExecuteSQL (
  "SELECT MAX(\"稼働日\")
     FROM \"稼働日重要指数\"
    WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_text ; category ) ;
workDays_raw = Case (
  ( IsEmpty ( workDays_raw1 ) or workDays_raw1 = "?" ) and not IsEmpty ( selYM_num ) ;
  ExecuteSQL (
  "SELECT MAX(\"稼働日\")
     FROM \"稼働日重要指数\"
    WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_num ; category ) ;
  workDays_raw1 ) ;
workDays = Max ( 0 ; Min ( 22 ; GetAsNumber ( workDays_raw ) ) ) ;

/* ========= 行生成（「稼働日」を見るよう変更） ========= */
rows = While (
  [ d = 1 ; html = "" ] ;
  d ≤ 22 ;
  [
    r1 = ExecuteSQL (
"SELECT
  \"稼働日\",
  \"必要売上\",
  \"計上売上\",
  \"必要進捗\",
  \"実績進捗\",
  \"前月\",
  \"対比\",
  \"日計\",
  \"進捗率\"
FROM
  \"稼働日重要指数\"
WHERE
  \"年月\" = ? AND
  \"稼働日\" = ? AND
  \"重要指数分類\" = ?"
; "|" ; "" ; selYM_text ; d ; category ) ;

    r2 = Case (
      ( r1 = "?" or IsEmpty ( r1 ) ) and not IsEmpty ( selYM_num ) ;
      ExecuteSQL (
"SELECT
  \"稼働日\",
  \"必要売上\",
  \"計上売上\",
  \"必要進捗\",
  \"実績進捗\",
  \"前月\",
  \"対比\",
  \"日計\",
  \"進捗率\"
FROM
  \"稼働日重要指数\"
WHERE
  \"年月\" = ? AND
  \"稼働日\" = ? AND
  \"重要指数分類\" = ?"
; "|" ; "" ; selYM_num ; d ; category ) ;
      "" ) ;

    raw = Case ( not IsEmpty ( r1 ) and r1 ≠ "?" ; r1 ;
                 not IsEmpty ( r2 ) and r2 ≠ "?" ; r2 ; "" ) ;
    vals = Substitute ( raw ; "|" ; "¶" ) ;

    _稼働日   = GetAsNumber ( GetValue ( vals ; 1 ) ) ;
    _必要売上 = GetAsNumber ( GetValue ( vals ; 2 ) ) ;
    _計上売上 = GetAsNumber ( GetValue ( vals ; 3 ) ) ;
    _必要進捗 = GetValue     ( vals ; 4 ) ;
    _実績進捗 = GetValue     ( vals ; 5 ) ;
    _前月     = GetAsNumber ( GetValue ( vals ; 6 ) ) ;
    _対比     = GetAsNumber ( GetValue ( vals ; 7 ) ) ;
    _日計     = GetAsNumber ( GetValue ( vals ; 8 ) ) ;
    _進捗率   = GetValue     ( vals ; 9 ) ;

    _差額 = Case ( not IsEmpty ( raw ) ; _計上売上 - _必要売上 ; "" ) ;
    clsDiff = Case ( GetAsNumber ( _差額 ) < 0 ; "neg" ; "pos" ) ;

    /* ▼ 必要進捗 % 付与（空なら計上/必要×100で補完） */
    _必要進捗_disp = Case (
      IsEmpty ( _必要進捗 ) ;
        Case ( _必要売上 > 0 and not IsEmpty ( _計上売上 ) ;
               Round ( _計上売上 / _必要売上 * 100 ; 0 ) & "%" ;
               "" ) ;
      PatternCount ( _必要進捗 ; "%" ) > 0 ; _必要進捗 ;
      _必要進捗 & "%"
    ) ;

    /* ▼ 実績進捗 % 付与 */
    _実績進捗_disp = Case (
      IsEmpty ( _実績進捗 ) ; "" ;
      PatternCount ( _実績進捗 ; "%" ) > 0 ; _実績進捗 ;
      _実績進捗 & "%"
    ) ;

    /* ▼ 進捗率 % 付与 */
    _進捗率_disp = Case (
      IsEmpty ( _進捗率 ) ; "" ;
      PatternCount ( _進捗率 ; "%" ) > 0 ; _進捗率 ;
      _進捗率 & "%"
    ) ;

    /* ▼ マイナス値の赤字クラス（数値列） */
    clsNec  = Case ( GetAsNumber ( _必要売上 ) < 0 ; "neg" ; "" ) ;
    clsAct  = Case ( GetAsNumber ( _計上売上 ) < 0 ; "neg" ; "" ) ;
    clsPre  = Case ( GetAsNumber ( _前月 )     < 0 ; "neg" ; "" ) ;
    clsComp = Case ( GetAsNumber ( _対比 )     < 0 ; "neg" ; "" ) ;
    clsDay  = Case ( GetAsNumber ( _日計 )     < 0 ; "neg" ; "" ) ;

    html = html &
    Case (
      d > workDays or IsEmpty ( raw ) ;
      "<tr><td class='day'>" & d & "日</td>" &
      "<td class='num'></td><td class='num'></td><td class='num'></td>" &
      "<td class='pct'></td><td class='pct'></td>" &
      "<td class='num'></td><td class='num'></td>" &
      "<td class='num sep'></td><td class='pct'></td></tr>" ;

      "<tr>" &
        "<td class='day'>" & _稼働日 & "日</td>" &
        "<td class='num " & clsNec  & "'>" & _必要売上 & "</td>" &
        "<td class='num " & clsAct  & "'>" & _計上売上 & "</td>" &
        "<td class='num " & clsDiff & "'>" & _差額 & "</td>" &
        "<td class='pct'>" & _必要進捗_disp & "</td>" &
        "<td class='pct'>" & _実績進捗_disp & "</td>" &
        "<td class='num " & clsPre  & "'>" & _前月 & "</td>" &
        "<td class='num " & clsComp & "'>" & _対比 & "</td>" &
        "<td class='num sep " & clsDay & "'>" & _日計 & "</td>" &
        "<td class='pct'>" & _進捗率_disp & "</td>" &
      "</tr>"
    ) ;

    d = d + 1
  ] ;
  html
) ;

/* ===== フッター（日計の合計） ===== */
foot_val = Let ([
  s1 = ExecuteSQL (
"SELECT SUM(\"日計\")
 FROM \"稼働日重要指数\"
 WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_text ; category ) ;
  s2 = Case ( ( s1 = "?" or IsEmpty ( s1 ) ) and not IsEmpty ( selYM_num ) ;
              ExecuteSQL (
"SELECT SUM(\"日計\")
 FROM \"稼働日重要指数\"
 WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_num ; category ) ;
              "" ) ;
  v  = Case ( not IsEmpty ( s1 ) and s1 ≠ "?" ; s1 ;
              not IsEmpty ( s2 ) and s2 ≠ "?" ; s2 ; "" )
] ; v ) ;

tfoot =
"<tr><td class='num' colspan='9' style='text-align:right;padding-right:12px'></td>
  <td class='num' style='background:#fff'>" & foot_val & "</td></tr>";

/* ========= 仕上げHTML ========= */
html =
  css &
  "<h3>＊" & titleMonth & "月度稼働日重要指数（" & category & "）</h3>
   <table>
     <thead>" & thead & "</thead>
     <tbody>" & rows & "</tbody>
     <tfoot>" & tfoot & "</tfoot>
   </table>
  </body></html>"
] ;

"data:text/html;base64," & Base64EncodeRFC ( 4648 ; html )
)

