  \"計上売上\",
  \"必要進捗\",
  \"実績進捗\",
  \"前月\",
  \"対比\",
  \"日計\",
  \"進捗率\"
FROM
  \"稼働日重要指数\"
WHERE
  \"年月\" = ? AND
  \"稼働日\" = ? AND
  \"重要指数分類\" = ?"
; "|" ; "" ; selYM_num ; d ; category ) ;
      "" ) ;

    raw = Case ( not IsEmpty ( r1 ) and r1 ≠ "?" ; r1 ;
                 not IsEmpty ( r2 ) and r2 ≠ "?" ; r2 ; "" ) ;
    vals = Substitute ( raw ; "|" ; "¶" ) ;

    _稼働日   = GetAsNumber ( GetValue ( vals ; 1 ) ) ;
    _必要売上 = GetAsNumber ( GetValue ( vals ; 2 ) ) ;
    _計上売上 = GetAsNumber ( GetValue ( vals ; 3 ) ) ;
    _必要進捗 = GetValue     ( vals ; 4 ) ;
    _実績進捗 = GetValue     ( vals ; 5 ) ;
    _前月     = GetAsNumber ( GetValue ( vals ; 6 ) ) ;
    _対比     = GetAsNumber ( GetValue ( vals ; 7 ) ) ;
    _日計     = GetAsNumber ( GetValue ( vals ; 8 ) ) ;
    _進捗率   = GetValue     ( vals ; 9 ) ;

    _差額 = Case ( not IsEmpty ( raw ) ; _計上売上 - _必要売上 ; "" ) ;
    clsDiff = Case ( GetAsNumber ( _差額 ) < 0 ; "neg" ; "pos" ) ;

    /* ▼ 必要進捗 % 付与（空なら計上/必要×100で補完） */
    _必要進捗_disp = Case (
      IsEmpty ( _必要進捗 ) ;
        Case ( _必要売上 > 0 and not IsEmpty ( _計上売上 ) ;
               Round ( _計上売上 / _必要売上 * 100 ; 0 ) & "%" ;
               "" ) ;
      PatternCount ( _必要進捗 ; "%" ) > 0 ; _必要進捗 ;
      _必要進捗 & "%"
    ) ;

    /* ▼ 実績進捗 % 付与 */
    _実績進捗_disp = Case (
      IsEmpty ( _実績進捗 ) ; "" ;
      PatternCount ( _実績進捗 ; "%" ) > 0 ; _実績進捗 ;
      _実績進捗 & "%"
    ) ;

    /* ▼ 進捗率 % 付与 */
    _進捗率_disp = Case (
      IsEmpty ( _進捗率 ) ; "" ;
      PatternCount ( _進捗率 ; "%" ) > 0 ; _進捗率 ;
      _進捗率 & "%"
    ) ;

    /* ▼ マイナス値の赤字クラス（数値列） */
    clsNec  = Case ( GetAsNumber ( _必要売上 ) < 0 ; "neg" ; "" ) ;
    clsAct  = Case ( GetAsNumber ( _計上売上 ) < 0 ; "neg" ; "" ) ;
    clsPre  = Case ( GetAsNumber ( _前月 )     < 0 ; "neg" ; "" ) ;
    clsComp = Case ( GetAsNumber ( _対比 )     < 0 ; "neg" ; "" ) ;
    clsDay  = Case ( GetAsNumber ( _日計 )     < 0 ; "neg" ; "" ) ;

    html = html &
    Case (
      d > workDays or IsEmpty ( raw ) ;
      "<tr><td class='day'>" & d & "日</td>" &
      "<td class='num'></td><td class='num'></td><td class='num'></td>" &
      "<td class='pct'></td><td class='pct'></td>" &
      "<td class='num'></td><td class='num'></td>" &
      "<td class='num sep'></td><td class='pct'></td></tr>" ;

      "<tr>" &
        "<td class='day'>" & _稼働日 & "日</td>" &
        "<td class='num " & clsNec  & "'>" & _必要売上 & "</td>" &
        "<td class='num " & clsAct  & "'>" & _計上売上 & "</td>" &
        "<td class='num " & clsDiff & "'>" & _差額 & "</td>" &
        "<td class='pct'>" & _必要進捗_disp & "</td>" &
        "<td class='pct'>" & _実績進捗_disp & "</td>" &
        "<td class='num " & clsPre  & "'>" & _前月 & "</td>" &
        "<td class='num " & clsComp & "'>" & _対比 & "</td>" &
        "<td class='num sep " & clsDay & "'>" & _日計 & "</td>" &
        "<td class='pct'>" & _進捗率_disp & "</td>" &
      "</tr>"
    ) ;

    d = d + 1
  ] ;
  html
) ;

/* ===== フッター（日計の合計） ===== */
foot_val = Let ([
  s1 = ExecuteSQL (
"SELECT SUM(\"日計\")
 FROM \"稼働日重要指数\"
 WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_text ; category ) ;
  s2 = Case ( ( s1 = "?" or IsEmpty ( s1 ) ) and not IsEmpty ( selYM_num ) ;
              ExecuteSQL (
"SELECT SUM(\"日計\")
 FROM \"稼働日重要指数\"
 WHERE \"年月\" = ? AND \"重要指数分類\" = ?" ; "" ; "" ; selYM_num ; category ) ;
              "" ) ;
  v  = Case ( not IsEmpty ( s1 ) and s1 ≠ "?" ; s1 ;
              not IsEmpty ( s2 ) and s2 ≠ "?" ; s2 ; "" )
] ; v ) ;

tfoot =
"<tr><td class='num' colspan='9' style='text-align:right;padding-right:12px'></td>
  <td class='num' style='background:#fff'>" & foot_val & "</td></tr>";

/* ========= 仕上げHTML ========= */
html =
  css &
  "<h3>＊" & titleMonth & "月度稼働日重要指数（" & category & "）</h3>
   <table>
     <thead>" & thead & "</thead>
     <tbody>" & rows & "</tbody>
     <tfoot>" & tfoot & "</tfoot>
   </table>
  </body></html>"
] ;

"data:text/html;base64," & Base64EncodeRFC ( 4648 ; html )
)

Let ( [
/* ========= CSS/ヘッダ ========= */
css = 
"<!doctype html>
<html lang='ja'>
<head>
<meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1'>
<style>
html,body {
  margin:0; padding:0; width:100%; height:100%;
  background:#fff; overflow:hidden; box-sizing:border-box;
}
* { box-sizing:border-box; }

/* 見出しを少しだけ低く */
h3 {
  text-align:center;
  margin:2px 0;
  padding:4px;
  font-size:13px;
  background:#f9b9d1;
  border-radius:4px;
}

.container {
  display:flex; flex-direction:column; gap:3px;
  width:100%; height:100%; margin:0; padding:0 2px 2px;
}

table {
  border-collapse:collapse; width:100%;
  font-size:11.5px;
  margin:0; table-layout:auto;
}

/* 行の高さを詰める */
th, td {
  border:1px solid #444;
  padding:2px 4px;
  line-height:1.15;
  text-align:right;
  overflow:visible;
  white-space:normal;
  word-break:break-all;
}

th {
  background:#ffe5f0;
  font-weight:bold;
  text-align:center;
}

/* 1列目だけは折返しOK */
td:first-child, th:first-child {
  text-align:left;
  white-space:normal;
  word-break:break-word;
  max-width:none;
}

/* 2列目の左寄せは維持 */
td:nth-child(2) { background:#fbeadf; text-align:left; }
td:nth-child(3) { background:#eaf3e0; }
td:nth-child(9), td:nth-child(10), td:nth-child(11) { background:#fff7a8; }
td:nth-child(n+12) { background:#d7ebfb; }

tr.total td { background:none !important; font-weight:bold; }

td, th { position:relative; transition:background-color .12s ease-in-out, outline-color .12s ease-in-out; }
td:hover { background:#ffec99 !important; outline:2px solid rgba(255,180,0,.9); outline-offset:-2px; }
tr:hover td { filter:brightness(1.02); }

/* 正は着色しない。負だけ赤太字 */
td.negative { color:#b42318; font-weight:bold; }

</style>
</head>
<body>
<div class='container'>" ;

