Let ( [
/* ========= CSS/ヘッダ ========= */
css = 
"<!doctype html>
<html lang='ja'>
<head>
<meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1'>
<style>
html,body {
