}

/* 1列目だけは折返しOK */
td:first-child, th:first-child {
  text-align:left;
  white-space:normal;
  word-break:break-word;
  max-width:none;
}

/* 2列目の左寄せは維持 */
td:nth-child(2) { background:#fbeadf; text-align:left; }
td:nth-child(3) { background:#eaf3e0; }
td:nth-child(9), td:nth-child(10), td:nth-child(11) { background:#fff7a8; }
