Step.StepText:
フィールド内容の全置換 [ 実績集計テーブル::SV担当者CD; 計算で置き換える: Let (
	[
	SVcode = ExecuteSQL ("
		SELECT \"ユーザーマスタ\".\"SV担当者CD\" FROM \"ユーザーマスタ\"
		JOIN \"tagging中間テーブル\"
			ON \"tagging中間テーブル\".\"タグID\" = \"ユーザーマスタ\".\"タグID\"
		AND \"tagging中間テーブル\".\"カテゴリID\" = ?
		AND \"tagging中間テーブル\".\"tagabble_id\" = ?
		AND \"tagging中間テーブル\".\"適用期間_開始日\" <= ?
		AND \"tagging中間テーブル\".\"適用期間_連携用終了日\" >= ?
		" ;
		"" ; "" ;
		"C0003" ;
		実績集計テーブル::加盟店セットCD ;
		Date ( Right ( 実績集計テーブル::年月 ; 2 ) ; 1 ; Left ( 実績集計テーブル::年月 ; 4 ) ) ;
		Date ( Right ( 実績集計テーブル::年月 ; 2 ) ; 1 ; Left ( 実績集計テーブル::年月 ; 4 ) )
	)
	] ;

	Case (
	IsEmpty ( SVcode ) ; "999999" ;
	SVcode
	)
) ]
